/** Сериализация токенов в CSS и в TS-зеркало для сборки из `frontend/`. */

import type {
  ShadowLayer,
  ShadowScale,
  ThemePalette,
} from "./tokens.ts";
import {
  darkPalette,
  darkShadows,
  lightPalette,
  lightShadows,
  motion,
  radius,
  space,
} from "./tokens.ts";

const GENERATED_BANNER =
  "/* AUTO-GENERATED by packages/theme/scripts/generate.ts — не редактируйте вручную. */";

export function cssVarName(key: string): string {
  return key.replace(/[A-Z]/g, (char) => `-${char.toLowerCase()}`);
}

export function px(value: number): string {
  return `${value}px`;
}

export function cssShadow(layers: readonly ShadowLayer[]): string {
  return layers
    .map(({ x, y, blur, spread, rgb, opacity }) => {
      const spreadPart = spread ? ` ${spread}px` : "";
      return `${x} ${px(y)} ${px(blur)}${spreadPart} rgb(${rgb.join(" ")} / ${opacity}%)`;
    })
    .join(", ");
}

export function cssEasing(points: readonly number[]): string {
  return `cubic-bezier(${points.join(", ")})`;
}

function paletteLines(palette: ThemePalette): string[] {
  return Object.entries(palette).map(
    ([key, value]) => `  --${cssVarName(key)}: ${value};`,
  );
}

function shadowLines(shadows: ShadowScale): string[] {
  return Object.entries(shadows).map(
    ([key, layers]) => `  --shadow-${key}: ${cssShadow(layers)};`,
  );
}

function radiusLines(): string[] {
  return Object.entries(radius).map(
    ([key, value]) => `  --radius-${key}: ${px(value)};`,
  );
}

function spaceLines(): string[] {
  return Object.entries(space).map(
    ([key, value]) => `  --space-${key}: ${px(value)};`,
  );
}

function motionLines(): string[] {
  return [
    `  --ease-spring: ${cssEasing(motion.easing.spring)};`,
    `  --ease-bounce: ${cssEasing(motion.easing.bounce)};`,
    `  --duration-fast: ${motion.duration.fast}ms;`,
    `  --duration-normal: ${motion.duration.normal}ms;`,
    `  --duration-enter: ${motion.duration.enter}ms;`,
  ];
}

export function renderThemeCss(): string {
  const light = [
    ...paletteLines(lightPalette),
    "",
    ...shadowLines(lightShadows),
    "",
    ...radiusLines(),
    "",
    ...spaceLines(),
    "",
    ...motionLines(),
    "",
    "  color-scheme: light;",
  ];

  const dark = [
    ...paletteLines(darkPalette),
    "",
    ...shadowLines(darkShadows),
    "",
    "  color-scheme: dark;",
  ];

  return [
    GENERATED_BANNER,
    "",
    ":root {",
    ...light,
    "}",
    "",
    ':root[data-theme="dark"] {',
    ...dark,
    "}",
    "",
  ].join("\n");
}

function literal(value: unknown): string {
  if (typeof value === "string") {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(literal).join(", ")}]`;
  }
  if (value !== null && typeof value === "object") {
    const entries = Object.entries(value).map(
      ([key, item]) => `${/^[a-zA-Z_$][\w$]*$/.test(key) ? key : JSON.stringify(key)}: ${literal(item)}`,
    );
    return `{ ${entries.join(", ")} }`;
  }
  return String(value);
}

export function renderTokensModule(): string {
  const radiusPx = Object.fromEntries(
    Object.entries(radius).map(([key, value]) => [key, px(value)]),
  );
  const shadowsCss = Object.fromEntries(
    Object.entries(lightShadows).map(([key, layers]) => [key, cssShadow(layers)]),
  );
  const darkShadowsCss = Object.fromEntries(
    Object.entries(darkShadows).map(([key, layers]) => [key, cssShadow(layers)]),
  );

  return [
    GENERATED_BANNER,
    "",
    "// Канонический источник: packages/theme/src/tokens.ts",
    "",
    `export const lightColors = ${literal(lightPalette)} as const;`,
    "",
    `export const darkColors = ${literal(darkPalette)} as const;`,
    "",
    `export const radius = ${literal(radius)} as const;`,
    "",
    `export const radiusPx = ${literal(radiusPx)} as const;`,
    "",
    `export const space = ${literal(space)} as const;`,
    "",
    `export const shadows = ${literal(shadowsCss)} as const;`,
    "",
    `export const darkShadows = ${literal(darkShadowsCss)} as const;`,
    "",
    `export const motion = ${literal(motion)} as const;`,
    "",
    "export type ThemeColors = typeof lightColors;",
    "",
  ].join("\n");
}
